using System.Collections.Generic;public class Solution{public IList<int> FindSubstring(string s,string[]w){var o=new List<int>();if(w.Length==0)return o;int L=w[0].Length,k=w.Length;var need=new Dictionary<string,int>();foreach(var x in w)need[x]=need.GetValueOrDefault(x)+1;for(int off=0;off<L;off++){var have=new Dictionary<string,int>();int l=off,c=0;for(int r=off;r+L<=s.Length;r+=L){string x=s.Substring(r,L);if(!need.ContainsKey(x)){have.Clear();c=0;l=r+L;continue;}have[x]=have.GetValueOrDefault(x)+1;c++;while(have[x]>need[x]){string y=s.Substring(l,L);have[y]--;l+=L;c--;}if(c==k){o.Add(l);string y=s.Substring(l,L);have[y]--;l+=L;c--;}}}return o;}}
